"""LaTeX table for the proposed supplement section, generated from tables/ac_recal_all_points.csv.  Usage (repo root): python3 extensions/ac_recal/make_supp_table.py"""
import csv
from pathlib import Path
H = Path(__file__).resolve().parent; rows = [r for r in csv.DictReader(open(H / 'tables/ac_recal_all_points.csv'))]
L = ['% generated by extensions/ac_recal/make_supp_table.py from tables/ac_recal_all_points.csv', '\\begin{longtable}{llcccccc}',
     '\\toprule case & loads & $\\lambda$ & $\\sigma_{\\min}(J_g)$ & P1/A0 & P2/P1 (95\\% CI) & P3/P1 (95\\% CI) & P1$-$P3\\\\\\midrule\\endhead']
for r in rows:
    L.append('%s & %s & %.1f & %.2f & %.3f & %.3f (%.3f--%.3f) & %.3f (%.3f--%.3f) & %.3f\\\\' % (r['case'], 'const.\\ power' if r['load_model'] == 'pq' else 'const.\\ imp.', float(r['lam']), float(r['sigma_min_Jg']), float(r['P1/A0 pooled']),
             *[float(r[k]) for k in ('P2/P1 pooled','P2/P1 lo','P2/P1 hi','P3/P1 pooled','P3/P1 lo','P3/P1 hi')], float(r['diff P1-P3 (ratio to A0)'])))
L += ['\\bottomrule\\end{longtable}']; (H / 'tables/supp_ac_recal_table.tex').write_text('\n'.join(L) + '\n'); print('rows', len(rows))
